  ["850e901ef2b0e542"] = { "Gli spiriti del vento ci avranno anche lasciati, ma il potere degli elementi non è del tutto fuori portata per chi ha la pazienza di cercarlo.\n\nSe sei <iniziato/iniziata> alle vie dello sciamano, posso aiutarti a coglierlo.", "." },
  ["851578d66909027c"] = { "Si ricomincia da capo.", "." },
  ["851974837c00df4d"] = { "⟦Crimson Templar=Templare Cremisi⟧! Possiedo il tuo stemma di richiamo. Rispondi alla mia chiamata!", "." },
  ["8519e12138fc368d"] = { "Seguimi, {name}. Ti porterò al nascondiglio dei Defias. Ma faresti meglio a proteggermi, o per me è finita.", "." },
  ["851ef05af941f559"] = { "Di nuovo qui, {name}? Cos'hai stavolta?", "." },
  ["851fddc6197265cf"] = { "Persino tra fredde mura di pietra come quelle che proteggono questa città, si possono trovare tranquillità e pace. Anzi, puoi trovarle ovunque tu sia... basta che cerchi un tale equilibrio dentro di te.", "." },
  ["852043da33478149"] = { "Salute! Se sei qui per accedere agli schemi di ingegneria goblin, tieni pronta la tua tessera di socio degli ingegneri goblin per la verifica.", "." },
  ["852e85f71480ab26"] = { "Sembra che dovrai andare avanti fino a ⟦Ratchet=Porto Paranco⟧ e dire a ⟦Sputtervalve=Sputavalvole⟧ che ho distrutto il segatronchi.", "." },
  ["8537f849e0921eeb"] = { "Quanti dei nostri luogotenenti sono ancora vivi, ⟦Drek'Thar=Drek'thar⟧?", "." },
  ["853b95b261782b37"] = { "Bah, sciocchezze! Muori!", "." },
  ["853c3a8b22348fbb"] = { "Mantenete la linea! Proteggete il re a ogni costo!", "." },
  ["853c745c662773e7"] = { "L'infestazione del Flagello cresce nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧. Serve ogni guerriero abile per arginare la marea della loro invasione.\n\nNecropoli rimanenti: $2282W", "." },
  ["854321ba18e23842"] = { "%s prende la mira un'ultima volta...", "." },
  ["8545b0113b99f5f9"] = { "%s si ferma e guarda il mare di soldati che gli stanno davanti, nervosi.", "." },
  ["85469c4bb8de9b90"] = { "Grazie... a te...", "." },
  ["8548839975bb711d"] = { "%s ascolta la supplica di {name}.", "." },
  ["854889853ddcb45f"] = { "%s consegna gli occhiali luminosi al dottor Erbanera.", "." },
  ["855bffede6056c66"] = { "Molto bene, che il tuo viaggio nella sartoria abbia inizio.", "." },
  ["8563b2771dca1c5d"] = { "La tua presenza ci rinsalda i nervi, <signore/signora> {name}.", "." },
  ["8564b38d57ef1c3f"] = { "Cerchi la morte?", "." },
  ["856913a4d5e0b006"] = { "Hai trovato la pagina di cui ti ho parlato, {name}?", "." },
  ["85722db6f8e8da8f"] = { "Un dispositivo pericoloso è questo, {name}. Mi rallegra che tu me l'abbia segnalato.", "." },
  ["8573a15ba514a91c"] = { "Ah, eccolo.", "." },
  ["857ce80e42957455"] = { "Non è giusto! Mio carissimo Sully! Torna da me! No, {name}! Perché mi hai portato una notizia simile!", "." },
  ["857d73eb810407e1"] = { "Ti auguro buone feste, <amico/amica>!", "." },
  ["85809571b5e722c9"] = { "Brzzzzt!\n\n<Benvenuto/Benvenuta> al Matrix Punchograph 3005 barra A, un terminale di livello di sicurezza alfa.\n\nRilevata scheda perforata bianca. Accesso consentito.\n\n01010100 01100101 01101100 01101100 00100000 01111001 01101111 01110101 01110010 00100000 01100110 01110010 01101001 01100101 01101110 01100100 01110011 00100000 01110100 01101111 00100000 01110000 01101100 01100001 01111001 00100000 01010111 01101111 01010111", "." },
  ["8582e8b13e8398a8"] = { "Tutti presenti, SIGNORE!", "." },
  ["8587ed0852ae4cb5"] = { "Be', <amico/amica> <mio/mia>, hai più abilità di me. Perché non vai a cercare il mio vecchio amico ⟦Rotgath Stonebeard=Rotgath Barbapietra⟧? È rimasto a ⟦Ironforge=Forgiardente⟧ quando ho lasciato la città per unirmi all'esercito di Jaina. Di sicuro saprà insegnarti qualcosa, o almeno conoscerà qualcuno che possa farlo. Se è ancora in giro, lo troverai di certo alla ⟦Great Forge=Grande Forgia⟧.", "." },
  ["858ddc242bce6101"] = { "Di nuovo a casa, di nuovo a casa.", "." },
  ["8592141808887936"] = { "Posso mostrarti qualche trucco... se prima non ti dispiace fare una piccola cosa per me, s'intende.", "." },
  ["859378632d323e66"] = { "Stai scherzando, vero? Credo che tu stia cercando L'ALTRO tizio basso, ⟦Thonys Pillarstone=Thonys Pernoforte⟧. È al piano di sotto. E ora smamma!", "." },
  ["859e286ab2af55cd"] = { "Madre, oh madre. Avresti dovuto ascoltarmi...", "." },
