  ["85af21342cbf9d50"] = { "Gli affari devono andare bene giù al bazar. Gli procuro subito nuove scorte!", "." },
  ["85be89d98dc58094"] = { "Ti voglio bene anch'io :).", "." },
  ["85cf09aa02268fb9"] = { "La tua vita è perduta!", "." },
  ["85d1c56c1b1479ab"] = { "Salute, {class}. La ⟦The Ironforge Brigade=Brigata di Forgiardente⟧ è di stanza qui per tenere d'occhio l'⟦Hive'Zora=Alveare Zora⟧. I druidi del ⟦Cenarion Circle=Circolo Cenariano⟧ stanno monitorando i movimenti dei silitidi e si aspettano qualcosa di grosso in quest'area.", "." },
  ["85d5cd356d54be57"] = { "Affrontami, se ne hai il coraggio!", "." },
  ["85d5da9666ce4e62"] = { "Molte sono le vie della Madre Terra. Che i tuoi antenati veglino su di te, {class}.", "." },
  ["85d73f6761c334a3"] = { "⟦Feralas: A History=Feralas: Una Storia⟧... Mmmm... Fammi esaminare questo per un momento.", "." },
  ["85e326dcffcebb64"] = { "È ora di portare fuori la spazzatura!", "." },
  ["85e3f9d5920255d6"] = { "Il ⟦Cenarion Circle=Circolo Cenariano⟧ è saggio, e ha esplorato molti dei segreti della terra. Gli artigiani farebbero bene a dare ascolto alle parole di questi druidi.", "." },
  ["85ed3006a910ac87"] = { "Poiché mi hai aiutato, ti dirò ciò che so di questa terra e delle cose che ci sono da vedere. Le mie conoscenze non sono vaste, ma forse posso indicarti qualcosa che potrebbe interessare qualcuno come te.", "." },
  ["85ee9268f7509c20"] = { "Perché mai vorresti farmi del male!? Vieni. Amici possiamo essere!", "." },
  ["85f0eff6582e36d5"] = { "%s comincia a incanalare la sua energia, concentrandosi sulla pietra.", "." },
  ["85f70c00c4bb6686"] = { "Oh!!! Tieni quella cosa lontana da me!", "." },
  ["85f8a80bb8e36708"] = { "Vattene, feccia rozza! L'⟦Alliance=Alleanza⟧ prevarrà nella ⟦Alterac Valley=Valle d'Alterac⟧!", "." },
  ["85fc9beb60c98570"] = { "Allievo non vale niente, maestro! Allievo chiede scusa per sua mancanza!", "." },
